import json

with open('tools/compiled_aves.json', 'r', encoding='utf-8') as f:
    aves = json.load(f)

print(f"Loaded {len(aves)} birds.")

# Generate JS code for buildFullDataset
js_lines = []
js_lines.append("  function buildFullDataset() {")
