    name = a['name'].replace("'", "\\'")
    sciname = a['sciname'].replace("'", "\\'")
    role = a['role'].replace("'", "\\'")
    loc = a['loc'].replace("'", "\\'")
    alert = a['alert'].replace("'", "\\'")
    img = a['img'].replace("'", "\\'")
