js_lines.append("    ];")
js_lines.append("    avesData.forEach(a => taxa.push({ id: a[0], name: a[1], sciname: a[2], cat: 1, role: a[3], loc: a[4], alert: a[5], img: a[6] }));")

# Mamiferos
js_lines.append("\n    // 2. MAMÍFEROS (10 Taxones reales de Mastofauna)")
